@RestController @RequestMapping("/shop/admin")
public class ShopAdminController {
 @Autowired ShopService s;
 @GetMapping("/enterprise-options") @PreAuthorize("@ss.hasAnyPermi('shop:manage,shop:catalog')") public AjaxResult enterpriseOptions(){return AjaxResult.success(s.jdbc().queryForList("select id,nickname,enterprise_state from shop_member where enterprise_state='approved'"));}

 @Autowired ShopWorkflow workflow;
 private String who(){return SecurityUtils.getUsername();}
 @PreAuthorize("@ss.hasAnyPermi('shop:manage,shop:finance')") @GetMapping("/overview") public AjaxResult overview(){Map<String,Object> result=new HashMap<>();result.put("orders",s.jdbc().queryForList("select status,count(*) count from shop_order where is_test=0"+s.officialOrder("shop_order.id")+" group by status"));result.put("members",s.jdbc().queryForObject("select count(*) from shop_member where is_test=0",Long.class));result.put("sales",s.jdbc().queryForObject("select coalesce(sum(amount-refunded_amount),0) from shop_order where status in ('paid','shipping','shipped','completed') and is_test=0"+s.verifiedPayment("shop_order.id"),Long.class));result.put("refunds",s.jdbc().queryForObject("select coalesce(sum(case when status='refunded' then amount else refunded_amount end),0) from shop_order where paid_at is not null and is_test=0"+s.verifiedPayment("shop_order.id"),Long.class));result.put("applications",s.jdbc().queryForObject("select coalesce(sum((enterprise_state='pending')+(distributor_state='pending')),0) from shop_member where is_test=0",Long.class));result.put("pendingCases",s.jdbc().queryForObject("select (select count(*) from shop_case where status in ('pending','returned','inspecting','awaiting_reship','awaiting_refund')"+s.officialOrder("shop_case.order_id")+")+(select count(*) from shop_after_sale where status='pending'"+s.officialOrder("shop_after_sale.order_id")+")",Long.class));result.put("pendingInvoices",s.jdbc().queryForObject("select count(*) from shop_invoice where status in ('requested','adjustment_required')"+s.officialOrder("shop_invoice.order_id"),Long.class));if(SecurityUtils.hasPermi("shop:manage")||SecurityUtils.hasPermi("shop:customer"))result.put("pendingReplies",s.jdbc().queryForObject("select count(*) from shop_chat c where exists(select 1 from shop_chat_message m where m.chat_id=c.id and m.sender='member' and m.id>c.staff_read_id)",Long.class));result.put("events",s.jdbc().queryForList("select * from shop_event order by id desc limit 12"));return AjaxResult.success(result);}
 @PreAuthorize("@ss.hasAnyPermi('shop:manage,shop:catalog,shop:warehouse,shop:content')") @GetMapping("/products") public AjaxResult products(){return AjaxResult.success(s.jdbc().queryForList("select * from shop_product where archived=0 order by id"));}
 @PreAuthorize("@ss.hasAnyPermi('shop:manage,shop:catalog')") @PostMapping("/products") @Transactional public AjaxResult product(@RequestBody JSONObject b){s.one("select content from shop_config where config_key='product_series' for update");if(b.containsKey("series")){String series=str(b.get("series")).trim();check(series.isEmpty()||s.productSeries().contains(series),"请选择现有产品系列，请先在系列设置中添加");b.put("series",series);}check(str(b.get("name")).trim().length()>=2&&str(b.get("name")).length()<=120,"商品名称需2至120字");check(b.getLongValue("price")>0&&b.getLongValue("wholesale")>=0&&b.getIntValue("stock")>=0&&b.getIntValue("pack")>=1,"请检查价格、库存和整箱数量");for(String key:new String[]{"price","wholesale","stock","pack"})integer(b.get(key),("stock".equals(key)||"wholesale".equals(key))?0:1,100000000,"价格、库存和包装数量必须是有效整数");check(str(b.get("image")).startsWith("/"),"请上传商品主图");JSONArray gallery=b.getJSONArray("gallery");String images=gallery==null?"[]":gallery.toJSONString();
  JSONObject pricing=b.getJSONObject("pricing");if(pricing==null)pricing=JSON.parseObject(str(b.get("pricing_json")).isEmpty()?"{}":str(b.get("pricing_json")));JSONObject cleanPricing=new JSONObject();for(String key:new String[]{"tiers","agreements"}){JSONArray rows=pricing.getJSONArray(key);if(rows==null)rows=new JSONArray();check(rows.size()<=50,"定价规则最多50条");Set<Long> seen=new HashSet<>();for(int i=0;i<rows.size();i++){JSONObject row=rows.getJSONObject(i);long value=integer(row.get("tiers".equals(key)?"quantity":"memberId"),1,100000000,"定价条件必须为正整数");check(seen.add(value),"定价条件不能重复");integer(row.get("price"),1,100000000,"定价必须为整数分");if("agreements".equals(key))s.one("select id from shop_member where id=? and enterprise_state='approved'",value);}cleanPricing.put(key,rows);}
  String spec=str(b.get("spec")).trim();check(!spec.isEmpty()&&spec.length()<=60,"规格需1至60字");b.put("spec",spec);check(s.rules().getJSONArray("categories").contains(str(b.get("category"))),"请选择现有商品分类");long family=b.getLongValue("family_id");if(family>0){Map<String,Object> parent=s.one("select id,family_id from shop_product where id=? for update",family);check(number(parent.get("family_id"))==0||number(parent.get("family_id"))==family,"请从原商品新增同款规格");}long root=family>0?family:b.getLongValue("id");if(root>0)check(s.jdbc().queryForObject("select count(*) from shop_product where archived=0 and (id=? or family_id=?) and spec=? and id<>?",Long.class,root,root,spec,b.getLongValue("id"))==0,"同款商品已有此规格，请编辑原规格");
  if(b.getLongValue("id")==0){s.jdbc().update("insert into shop_product(name,category,spec,price,wholesale,stock,pack,image,gallery,detail,enabled,family_id,pricing_json) values(?,?,?,?,?,?,?,?,?,?,?,?,?)",b.get("name"),b.get("category"),b.get("spec"),b.get("price"),b.get("wholesale"),b.get("stock"),b.get("pack"),b.get("image"),images,b.get("detail"),b.getBooleanValue("enabled"),family,cleanPricing.toJSONString());}
  else{Map<String,Object> old=s.one("select * from shop_product where id=? for update",b.get("id"));check(number(old.get("archived"))==0,"商品已删除，请刷新列表");check(b.containsKey("version")&&number(old.get("version"))==integer(b.get("version"),0,Long.MAX_VALUE,"商品版本不正确"),"商品或库存已变化，请刷新后编辑");s.jdbc().update("update shop_product set name=?,category=?,spec=?,price=?,wholesale=?,pack=?,image=?,gallery=?,detail=?,enabled=?,family_id=?,pricing_json=?,version=version+1 where id=?",b.get("name"),b.get("category"),b.get("spec"),b.get("price"),b.get("wholesale"),b.get("pack"),b.get("image"),images,b.get("detail"),b.getBooleanValue("enabled"),family,cleanPricing.toJSONString(),b.get("id"));}if(b.getLongValue("id")==0)b.put("id",s.jdbc().queryForObject("select last_insert_id()",Long.class));if(b.containsKey("series"))s.jdbc().update("update shop_product set series=? where id=?",b.getString("series"),b.getLongValue("id"));check(str(b.get("brand")).length()<=60,"品牌名称最多60字");s.jdbc().update("update shop_product set brand=?,retail_enabled=?,wholesale_enabled=?,sort_order=? where id=?",str(b.get("brand")),!b.containsKey("retail_enabled")||b.getBooleanValue("retail_enabled"),!b.containsKey("wholesale_enabled")||b.getBooleanValue("wholesale_enabled"),integer(b.getOrDefault("sort_order",0),0,100000,"排序须为0至100000"),b.get("id"));if(b.containsKey("minimum_tier"))s.jdbc().update("update shop_product set minimum_tier=? where id=?",integer(b.get("minimum_tier"),0,2,"请选择专享商品最低等级"),b.get("id"));String code=b.containsKey("productCode")?str(b.get("productCode")).trim().toUpperCase(java.util.Locale.ROOT):str(s.one("select product_code from shop_product where id=?",b.get("id")).get("product_code"));if(code.isEmpty())code="P"+String.format(java.util.Locale.ROOT,"%010d",b.getLongValue("id"));check(code.matches("[A-Z0-9][A-Z0-9_.-]{0,59}"),"商品编码为1至60位字母、数字、横线或点");check(s.jdbc().queryForObject("select count(*) from shop_product where product_code=? and id<>?",Long.class,code,b.get("id"))==0,"商品编码已使用，请换一个");s.jdbc().update("update shop_product set product_code=? where id=?",code,b.get("id"));if(b.containsKey("video_url")){String video=str(b.get("video_url")).trim();check(video.isEmpty()||(video.matches("/shop/videos/[a-f0-9-]{36}\\.mp4")&&s.jdbc().queryForObject("select count(*) from shop_product_video where path=?",Long.class,video)==1),"请先上传有效的商品视频");s.jdbc().update("update shop_product set video_url=? where id=?",video,b.get("id"));}s.warehouseEnsure(b.getLongValue("id"));s.event("product",b.getLongValue("id"),"保存商品",who());return AjaxResult.success();}
 @PreAuthorize("@ss.hasAnyPermi('shop:manage,shop:warehouse,shop:catalog')") @PostMapping("/products/{id}/stock") @Transactional public AjaxResult stock(@PathVariable long id,@RequestBody JSONObject b){long delta=integer(b.get("delta"),-100000000,100000000,"调整件数必须为整数");check(delta!=0,"请输入增加或减少的件数");String key=str(b.get("requestKey"));check(key.matches("[a-zA-Z0-9_-]{8,80}"),"请刷新库存调整窗口");check(str(b.get("note")).trim().length()>=2,"请填写库存调整原因");s.inventory(id,delta,"admin_"+key,str(b.get("note")),who());return AjaxResult.success();}
 @PreAuthorize("@ss.hasAnyPermi('shop:manage,shop:catalog,shop:warehouse,shop:content')") @GetMapping("/products/{id}/stock") public AjaxResult stockLog(@PathVariable long id){return AjaxResult.success(s.jdbc().queryForList("select * from shop_stock_log where product_id=? order by id desc limit 100",id));}
 @PreAuthorize("@ss.hasAnyPermi('shop:manage,shop:finance')") @GetMapping("/payments") public AjaxResult payments(){return AjaxResult.success(s.jdbc().queryForList("select o.channel,p.*,o.order_no,o.status,case when o.status='refunded' then o.amount else o.refunded_amount end refunded_amount"+ShopQueryFields.fields("o.member_id")+" from shop_payment p join shop_order o on o.id=p.order_id where 1=1"+s.verifiedPayment("o.id")+" order by p.paid_at desc"));}
 @PreAuthorize("@ss.hasAnyPermi('shop:manage,shop:finance')") @GetMapping("/commission-events") public AjaxResult commissionEvents(){return AjaxResult.success(s.jdbc().queryForList("select e.*,o.order_no from shop_commission_event e join shop_order o on o.id=e.order_id where 1=1"+s.officialOrder("o.id")+" order by e.id desc"));}
 @PreAuthorize("@ss.hasAnyPermi('shop:manage,shop:finance')") @GetMapping("/commissions") public AjaxResult commissions(){return AjaxResult.success(s.jdbc().queryForList("select c.*,o.order_no,o.channel,o.amount order_amount,m.nickname"+ShopQueryFields.fields("m.id")+" from shop_commission c join shop_order o on o.id=c.order_id join shop_member m on m.id=c.member_id where 1=1"+s.verifiedPayment("o.id")+" order by c.id desc"));}
 @PreAuthorize("@ss.hasAnyPermi('shop:manage,shop:content')") @GetMapping("/media") public AjaxResult media(){return AjaxResult.success(s.jdbc().queryForList("select * from shop_media order by section_name,slot"));}
 @PreAuthorize("@ss.hasAnyPermi('shop:manage,shop:content')") @PostMapping("/media/{slot}/{action}") @Transactional public AjaxResult mediaAction(@PathVariable String slot,@PathVariable String action,@RequestBody JSONObject b){Map<String,Object> m=s.one("select * from shop_media where slot=? for update",slot);
  if("content".equals(action)){String target=str(b.get("target"));check(Arrays.asList("none","product","category","business","distribution","coupons","campaigns","promo-materials").contains(target),"请选择有效跳转页面");if("product".equals(target))s.one("select id from shop_product where id=? and enabled=1",integer(b.get("productId"),1,Long.MAX_VALUE,"请选择商品"));check(str(b.get("title")).length()<=100&&str(b.get("subtitle")).length()<=200,"标题或说明过长");JSONObject config=new JSONObject();for(String key:new String[]{"title","subtitle","target","productId"})config.put(key,b.get(key));String channel=str(b.getOrDefault("channel","all"));check(Arrays.asList("all","C","B").contains(channel),"请选择广告适用渠道");String start=str(b.get("start")),end=str(b.get("end"));java.sql.Timestamp begin=start.isEmpty()?null:timestamp(start),finish=end.isEmpty()?null:timestamp(end);check(begin==null||finish==null||finish.after(begin),"结束时间须晚于开始时间");config.put("channel",channel);config.put("enabled",!b.containsKey("enabled")||b.getBooleanValue("enabled"));config.put("start",start);config.put("end",end);s.jdbc().update("update shop_media set config_draft=? where slot=?",config.toJSONString(),slot);}
  else if("draft".equals(action)){check(str(b.get("url")).startsWith("/"),"请先上传图片");s.jdbc().update("update shop_media set draft_url=? where slot=?",b.get("url"),slot);}
  else if("publish".equals(action)){check(!str(m.get("draft_url")).isEmpty(),"请先保存草稿图片");s.jdbc().update("update shop_media set has_previous=1,config_previous=config_live,config_live=config_draft,previous_url=published_url,published_url=draft_url where slot=?",slot);}
  else if("restore".equals(action)){check(Boolean.TRUE.equals(m.get("has_previous"))||"1".equals(str(m.get("has_previous"))),"暂无历史版本");s.jdbc().update("update shop_media set config_draft=config_previous,config_previous=config_live,config_live=config_draft,published_url=?,draft_url=?,previous_url=? where slot=?",m.get("previous_url"),m.get("previous_url"),m.get("published_url"),slot);}
  else if("default".equals(action)){s.jdbc().update("update shop_media set has_previous=1,config_previous=config_live,config_live=null,config_draft=null,previous_url=published_url,published_url=default_url,draft_url=default_url where slot=?",slot);}else throw new IllegalArgumentException("无效操作");s.event("media",0,slot+":"+action,who());return AjaxResult.success();}
 @PreAuthorize("@ss.hasAnyPermi('shop:manage,shop:catalog,shop:content,shop:finance')") @GetMapping("/rules") public AjaxResult rules(){return AjaxResult.success(s.rules());}
 @PreAuthorize("@ss.hasAnyPermi('shop:manage,shop:content')") @PostMapping("/rules") public AjaxResult rules(@RequestBody JSONObject b){String[] keys={"minimumWholesale","couponThreshold","couponDiscount","commissionPercent","withdrawMinimum","withdrawFee"};JSONObject clean=new JSONObject();for(String k:keys){check(b.containsKey(k)&&b.getLongValue(k)>=0&&b.getLongValue(k)<=100000000,"规则数值不正确");clean.put(k,integer(b.get(k),0,100000000,"规则数值必须是整数"));}if(!SecurityUtils.hasPermi("shop:manage")){JSONObject original=s.rules();for(String k:keys)check(clean.getLongValue(k)==original.getLongValue(k),"仅管理员可修改金额和佣金规则");}check(clean.getLongValue("commissionPercent")<=50,"佣金比例应在0%至50%之间");check(clean.getLongValue("couponDiscount")<=clean.getLongValue("couponThreshold"),"优惠不能超过使用门槛");check(clean.getLongValue("withdrawMinimum")>clean.getLongValue("withdrawFee"),"最低提现金额必须大于手续费");for(String option:Arrays.asList("simulationPaymentEnabled","walletPaymentEnabled")){boolean value=b.containsKey(option)?b.getBooleanValue(option):s.rules().getBooleanValue(option);if(!SecurityUtils.hasPermi("shop:manage"))check(value==s.rules().getBooleanValue(option),"仅管理员可修改付款开关");clean.put(option,value);}long workDays=integer(b.getOrDefault("withdrawWorkingDays",s.rules().get("withdrawWorkingDays")),1,30,"提现处理时限为1至30个工作日");if(!SecurityUtils.hasPermi("shop:manage"))check(workDays==s.rules().getLongValue("withdrawWorkingDays"),"仅管理员可修改提现时限");clean.put("withdrawWorkingDays",workDays);clean.put("brands",s.rules().getOrDefault("brands",new JSONArray()));String share=str(b.getOrDefault("shareBaseUrl",s.rules().getOrDefault("shareBaseUrl","https://meir.okam.top")));check(share.matches("https?://[a-zA-Z0-9.:-]+"),"推广网站地址应以http或https开头，不填写页面路径");clean.put("shareBaseUrl",share);clean.put("shopName",str(b.getOrDefault("shopName",s.rules().getOrDefault("shopName","美容商城"))));for(String key:new String[]{"servicePhone","serviceHours","serviceNotice","agreementText"}){String value=str(b.get(key));check(value.length()<=("agreementText".equals(key)?20000:1000),"服务内容过长");clean.put(key,value);}JSONArray categories=b.getJSONArray("categories");if(categories!=null){check(!categories.isEmpty()&&categories.size()<=100,"请保留1至100个分类");Set<String> seen=new HashSet<>();for(Object c:categories)check(!str(c).trim().isEmpty()&&str(c).length()<=40&&seen.add(str(c)),"分类不能空白或重复，最多40字");clean.put("categories",categories);}else clean.put("categories",s.rules().get("categories"));clean.put("commissionAfterReceipt",true);s.jdbc().update("update shop_config set content=? where config_key='rules'",clean.toJSONString());for(Object category:clean.getJSONArray("categories")){String name=str(category);if(Arrays.asList("洁面","精华","面霜","面膜","爽肤水").contains(name))continue;if(s.jdbc().queryForObject("select count(*) from shop_media where position_name=? and page_name='商品分类'",Long.class,name+"分类图")==0)s.jdbc().update("insert ignore into shop_media(slot,section_name,page_name,position_name,suggested_size,draft_url,published_url,previous_url,title,subtitle,default_url) values(?,'通用','商品分类',?,'300 × 300','','','','','','')","category.custom_"+s.hash(name).substring(0,20),name+"分类图");}s.event("rules",0,"保存新订单适用规则",who());return AjaxResult.success();}
 @PreAuthorize("@ss.hasAnyPermi('shop:manage,shop:customer')") @GetMapping("/members") public AjaxResult members(){List<Map<String,Object>> rows=s.jdbc().queryForList("select m.*,c.username"+ShopQueryFields.fields("m.id")+" from shop_member m left join shop_credentials c on c.member_id=m.id where m.is_test=0 order by m.id desc");for(Map<String,Object> m:rows)m.remove("identity_key");return AjaxResult.success(rows);}
 @PreAuthorize("@ss.hasAnyPermi('shop:manage,shop:customer')") @PostMapping("/members/{id}/{kind}") @Transactional public AjaxResult review(@PathVariable long id,@PathVariable String kind,@RequestBody JSONObject b){check("enterprise".equals(kind)||"distributor".equals(kind),"无效审核类型");Map<String,Object> m=s.one("select * from shop_member where id=? for update",id);check("pending".equals(m.get(kind+"_state")),"该申请不在待审核状态");String state=b.getString("state");check("approved".equals(state)||"rejected".equals(state),"无效审核结果");if("rejected".equals(state))check(str(b.get("note")).trim().length()>=2,"请说明驳回原因");s.jdbc().update("update shop_member set "+kind+"_state=?,"+kind+"_note=? where id=?",state,b.getString("note"),id);if("enterprise".equals(kind)&&"approved".equals(state))s.companyCertified(id);s.event(kind,id,state,who());return AjaxResult.success();}
 @PreAuthorize("@ss.hasAnyPermi('shop:manage,shop:warehouse,shop:customer,shop:finance')") @GetMapping("/orders") public AjaxResult orders(){List<Map<String,Object>> rows=s.jdbc().queryForList("select o.*,p.mode payment_mode,m.nickname,m.phone,(select group_concat(concat('第',a.depth,'级：',pm.nickname) order by a.depth separator '; ') from shop_distribution_attribution a join shop_member pm on pm.id=a.member_id where a.order_id=o.id) promotion_sources"+ShopQueryFields.fields("m.id")+" from shop_order o join shop_member m on m.id=o.member_id left join shop_payment p on p.order_id=o.id where m.is_test=0"+s.officialOrder("o.id")+" order by o.id desc");workflow.attachItemsWithProgress(rows);return AjaxResult.success(rows);}
 @PreAuthorize("@ss.hasAnyPermi('shop:manage,shop:warehouse')") @PostMapping("/orders/{id}/ship") public AjaxResult ship(@PathVariable long id,@RequestBody JSONObject b){workflow.ship(id,b,who());return AjaxResult.success();}
 @PreAuthorize("@ss.hasAnyPermi('shop:manage,shop:warehouse,shop:customer,shop:finance')") @GetMapping("/orders/{id}/shipments") public AjaxResult shipments(@PathVariable long id){return AjaxResult.success(workflow.shipments(id));}
 @PreAuthorize("@ss.hasAnyPermi('shop:manage,shop:customer,shop:finance')") @GetMapping("/cases") public AjaxResult cases(){return AjaxResult.success(workflow.cases(null));}
 @PreAuthorize("@ss.hasAnyPermi('shop:manage,shop:finance')") @PostMapping("/cases/{id}") public AjaxResult handleCase(@PathVariable long id,@RequestBody JSONObject b){workflow.handle(id,b,who());return AjaxResult.success();}

 @PreAuthorize("@ss.hasAnyPermi('shop:manage,shop:customer,shop:finance')") @GetMapping("/after-sales") public AjaxResult afterSales(){return AjaxResult.success(s.jdbc().queryForList("select o.channel,a.*,o.order_no,o.amount,o.status order_status"+ShopQueryFields.fields("o.member_id")+" from shop_after_sale a join shop_order o on o.id=a.order_id where 1=1"+s.officialOrder("o.id")+" order by a.id desc"));}
 @PreAuthorize("@ss.hasAnyPermi('shop:manage,shop:finance')") @PostMapping("/after-sales/{id}") @Transactional public AjaxResult refund(@PathVariable long id,@RequestBody JSONObject b){check(s.isDemo(),"该订单暂不支持在线退款，请联系财务核实");Map<String,Object> a=s.one("select * from shop_after_sale where id=? for update",id);check("pending".equals(a.get("status")),"该售后已处理");Map<String,Object> o=s.one("select * from shop_order where id=? for update",a.get("order_id"));String state=b.getString("state");check("refunded".equals(state)||"rejected".equals(state),"无效售后操作");check(!str(b.get("note")).trim().isEmpty(),"请填写处理说明");if("refunded".equals(state)){s.finance("refund","legacy_"+id,number(o.get("id")),number(o.get("amount")),0);check(s.jdbc().queryForObject("select count(*) from shop_case where order_id=?",Long.class,o.get("id"))==0,"请核对该订单商品售后记录后处理");s.jdbc().update("update shop_order set status='refunded',refunded_amount=amount,refunded_shipping_amount=shipping_amount where id=?",o.get("id"));s.returnOrderCoupon(number(o.get("id")));s.orderReceived(number(o.get("id")));if("paid".equals(o.get("status")))s.restoreStock(number(o.get("id")));s.jdbc().update("insert ignore into shop_commission_event(member_id,order_id,delta,event_key,note) select member_id,order_id,-amount,concat('legacy_refund_',order_id),'整单非实收退款扣回佣金' from shop_commission where order_id=?",o.get("id"));s.jdbc().update("update shop_commission set original_amount=coalesce(original_amount,amount),amount=0,status='reversed' where order_id=?",o.get("id"));}s.jdbc().update("update shop_after_sale set status=?,note=? where id=?",state,b.get("note"),id);s.event("afterSale",id,state,who());return AjaxResult.success();}
 @PreAuthorize("@ss.hasAnyPermi('shop:manage,shop:finance')") @GetMapping("/withdrawals") public AjaxResult withdrawals(){return AjaxResult.success(s.maskWithdrawals(s.jdbc().queryForList("select w.*,m.nickname"+ShopQueryFields.fields("m.id")+" from shop_withdrawal w join shop_member m on m.id=w.member_id where m.is_test=0 "+(s.isOfficialDisplay()?" and w.payment_mode<>'simulation' ":"")+" order by w.id desc")));}
 @PreAuthorize("@ss.hasAnyPermi('shop:manage,shop:finance')") @PostMapping("/withdrawals/{id}") @Transactional public AjaxResult withdrawal(@PathVariable long id,@RequestBody JSONObject b){check(s.isDemo(),"提现付款渠道尚未开通");Map<String,Object> w=s.one("select * from shop_withdrawal where id=? for update",id);s.one("select id from shop_member where id=? for update",w.get("member_id"));check(!who().equals(w.get("submitted_account"))&&s.jdbc().queryForObject("select count(*) from shop_credentials where member_id=? and username=?",Long.class,w.get("member_id"),who())==0,"提交人不能审核自己的提现，请另一名有权财务处理");String state=b.getString("state");check(Arrays.asList("paid","rejected","failed","unknown").contains(state),"无效提现处理");if(state.equals(w.get("status")))return AjaxResult.success();check(Arrays.asList("pending","unknown").contains(w.get("status")),"提现已处理");check(!("unknown".equals(w.get("status"))&&"rejected".equals(state)),"结果待核实的提现请先确认成功或失败，不能直接驳回");if("paid".equals(state))check(s.available(number(w.get("member_id")))>=0,"账户有佣金扣回，请先核对余额");check(!str(b.get("note")).trim().isEmpty(),"请填写处理说明");if("paid".equals(state))s.finance("withdrawal","withdraw_"+id,id,number(w.get("amount")),number(w.get("fee")));s.jdbc().update("update shop_withdrawal set status=?,note=?,reviewer=?,handled_at=now() where id=?",state,b.get("note"),who(),id);s.event("withdrawal",id,state,who());return AjaxResult.success();}
 @PreAuthorize("@ss.hasAnyPermi('shop:manage,shop:manage')") @PostMapping("/members/{id}/enabled") @Transactional public AjaxResult memberEnabled(@PathVariable long id,@RequestBody JSONObject b){s.one("select id from shop_member where id=? for update",id);s.jdbc().update("update shop_member set enabled=? where id=?",b.getBooleanValue("enabled"),id);if(!b.getBooleanValue("enabled"))s.jdbc().update("delete from shop_session where member_id=?",id);s.event("member",id,b.getBooleanValue("enabled")?"启用会员":"停用会员",who());return AjaxResult.success();}

 @GetMapping("/daily") @PreAuthorize("@ss.hasAnyPermi('shop:manage,shop:finance')") public AjaxResult daily(@RequestParam String from,@RequestParam String to,@RequestParam(defaultValue="")String channel,@RequestParam(defaultValue="all")String identity){check(Arrays.asList("","C","B").contains(channel),"请选择业务渠道");String buyer=ShopQueryFields.predicate("qo.member_id",identity),payee=ShopQueryFields.predicate("qw.member_id",identity);String scope=channel.isEmpty()&&"all".equals(identity)?"1=1":"((kind='withdrawal' and exists(select 1 from shop_withdrawal qw where qw.id=object_id and "+payee+")) or (kind<>'withdrawal' and exists(select 1 from shop_order qo where qo.id=object_id and "+buyer+(channel.isEmpty()?"":" and qo.channel='"+channel+"'")+")))";if(s.isOfficialDisplay())scope="("+scope+") and ((kind='withdrawal' and exists(select 1 from shop_withdrawal vw join shop_member vm on vm.id=vw.member_id where vw.id=object_id and vw.payment_mode<>'simulation' and vm.is_test=0)) or (kind<>'withdrawal' and exists(select 1 from shop_order vo where vo.id=object_id and vo.is_test=0 and not exists(select 1 from shop_payment vp where vp.order_id=vo.id and vp.mode='simulation'))))";java.time.LocalDate a=java.time.LocalDate.parse(from),b=java.time.LocalDate.parse(to);check(!b.isBefore(a)&&java.time.temporal.ChronoUnit.DAYS.between(a,b)<=366,"日期范围为1至367天");Map<String,Object> out=new HashMap<>();out.put("rows",s.jdbc().queryForList("select date(occurred_at) day,sum(case when kind='payment' then amount else 0 end) payments,sum(case when kind='refund' then amount else 0 end) refunds,sum(case when kind='withdrawal' then amount else 0 end) withdrawals,sum(case when kind='withdrawal' then fee else 0 end) fees,sum(case when kind='bank_received' then amount else 0 end) bank_received,sum(case when kind in ('bank_outcome','bank_return') then amount else 0 end) bank_returned from shop_finance_event where "+scope+" and occurred_at>=? and occurred_at<? group by date(occurred_at) order by day",a.toString(),b.plusDays(1).toString()));out.put("historicalUndated",s.jdbc().queryForList("select kind,sum(amount) amount,sum(fee) fee from shop_finance_event where "+scope+" and occurred_at is null group by kind"));out.put("basis","订单收退按所选渠道与购买人当前身份查询；提现按申请人身份筛选，跨渠道提现不按采购零售拆分。订单收退仅列示已核实的业务记录；对公实际核验收退单独列示，不能相加为实际银行余额。按北京时间记录发生日汇总，历史无日期交易另列。");return AjaxResult.success(out);}
 @GetMapping("/health") @PreAuthorize("@ss.hasAnyPermi('shop:manage,shop:access')") public AjaxResult health() throws java.io.IOException {java.nio.file.Path p=java.nio.file.Paths.get("/opt/meir-shop/runtime/ops-status.json");if(!java.nio.file.Files.exists(p)){s.jdbc().queryForObject("select 1",Integer.class);JSONObject local=new JSONObject();local.put("healthy",true);local.put("alerts",new JSONArray());local.put("scope","当前应用和数据库连通；备份结果请查看备份与运行维护");return AjaxResult.success(local);}JSONObject status=JSON.parseObject(new String(java.nio.file.Files.readAllBytes(p),java.nio.charset.StandardCharsets.UTF_8));if(System.currentTimeMillis()-java.nio.file.Files.getLastModifiedTime(p).toMillis()>900000){status.getJSONArray("alerts").add("巡检结果超过15分钟未更新");status.put("healthy",false);}return AjaxResult.success(status);}
}
